SELECT MIN(id) AS minId, MAX(id) AS maxId FROM hydra_task_task_node WHERE enable = 1 AND schedule_type = 'Cycle' AND schedule_cycle IN
#{cycle}
AND ( next_schedule_time IS NULL OR next_schedule_time <= #{targetTime} )

SELECT id, guid, owned_service_guid, name, schedule_cron, image_path, type, resource_type, deployment_method, priority, actually_priority, dry_run, schedule_cycle, schedule_type, schedule_start_time, schedule_end_time, enable, next_schedule_time, processor_name, create_time, update_time FROM hydra_task_task_node WHERE id >= #{idMin} AND id <= #{idMax} AND enable = 1 AND schedule_type = 'Cycle' AND schedule_cycle IN
#{cycle}
AND ( next_schedule_time IS NULL OR next_schedule_time <= #{targetTime} ) ORDER BY actually_priority DESC, id ASC
